import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
  useSyncExternalStore,
  type ReactNode,
} from 'react';
import { useColorScheme } from 'react-native';
import {
  readSystemAccessibility,
  subscribeToSystemAccessibility,
  type GlassyUiPreferences,
  type GlassyUiTheme,
} from './lib/preferences';
import { GLASS_COLORS } from './lib/tokens';

type PreferenceState = Required<GlassyUiPreferences>;

type PreferenceContextValue = {
  preferences: PreferenceState;
  setPreferences: (prefs: Partial<GlassyUiPreferences>) => void;
};

const PreferencesContext = createContext<PreferenceContextValue | null>(null);

function ignorePreferences() {}

/** The device's appearance and accessibility settings, as glass preferences. */
function useSystemPreferences(): PreferenceState {
  const scheme = useColorScheme();

  const accessibility = useSyncExternalStore(
    subscribeToSystemAccessibility,
    readSystemAccessibility,
    readSystemAccessibility,
  );

  return useMemo(
    () => ({
      theme: scheme === 'light' ? 'light' : 'dark',
      mode: 'clear',
      reduceMotion: accessibility.reduceMotion,
      reduceTransparency: accessibility.reduceTransparency,
    }),
    [accessibility, scheme],
  );
}

/**
 * Holds the glass preferences every component follows. It starts from the device's appearance,
 * Reduce Motion and Reduce Transparency settings; `defaultTheme` overrides the appearance until
 * the app sets a theme. Choices made with `setPreferences` last while the provider is mounted;
 * persist them in your app's own storage if they should survive a restart.
 */
export function GlassProvider({
  children,
  defaultTheme,
}: {
  children: ReactNode;
  defaultTheme?: GlassyUiTheme;
}) {
  const system = useSystemPreferences();
  const [explicit, setExplicit] = useState<GlassyUiPreferences>({});

  const preferences = useMemo(() => {
    const merged: PreferenceState = { ...system, ...explicit };

    if (defaultTheme && explicit.theme === undefined) merged.theme = defaultTheme;

    return merged;
  }, [defaultTheme, explicit, system]);

  const setPreferences = useCallback((next: Partial<GlassyUiPreferences>) => {
    setExplicit((previous) => ({ ...previous, ...next }));
  }, []);

  const value = useMemo(() => ({ preferences, setPreferences }), [preferences, setPreferences]);

  return <PreferencesContext.Provider value={value}>{children}</PreferencesContext.Provider>;
}

export const PreferencesProvider = GlassProvider;

/** The provider's preferences, or the device's own settings when no provider is mounted. */
export function useOptionalPreferences(): PreferenceContextValue {
  const context = useContext(PreferencesContext);
  const system = useSystemPreferences();

  return context ?? { preferences: system, setPreferences: ignorePreferences };
}

export function usePreferences() {
  const context = useContext(PreferencesContext);

  if (!context) {
    throw new Error('usePreferences must be used within GlassProvider');
  }

  return context;
}

/** The colours for the current theme, with the preferences they came from. */
export function useGlassTheme() {
  const { preferences } = useOptionalPreferences();

  return { colors: GLASS_COLORS[preferences.theme], preferences };
}

import { AccessibilityInfo, Platform } from 'react-native';

export type GlassyUiMode = 'clear' | 'tinted';

export type GlassyUiTheme = 'light' | 'dark';

export interface GlassyUiPreferences {
  theme?: GlassyUiTheme;
  /** Clear glass shows more of what lies behind it; tinted glass holds a denser frost. */
  mode?: GlassyUiMode;
  reduceTransparency?: boolean;
  reduceMotion?: boolean;
}

export type SystemAccessibility = {
  reduceMotion: boolean;
  reduceTransparency: boolean;
};

type Subscription = { remove: () => void };

// The system's accessibility settings, read once and shared by every glass component.
let snapshot: SystemAccessibility = { reduceMotion: false, reduceTransparency: false };

const listeners = new Set<() => void>();

let subscriptions: Subscription[] = [];

function update(next: Partial<SystemAccessibility>) {
  const merged = { ...snapshot, ...next };

  if (
    merged.reduceMotion === snapshot.reduceMotion &&
    merged.reduceTransparency === snapshot.reduceTransparency
  ) {
    return;
  }

  snapshot = merged;
  listeners.forEach((listener) => listener());
}

function warnReadFailure(cause: Error) {
  console.warn('Glassy UI could not read an accessibility setting', cause);
}

function startListening() {
  AccessibilityInfo.isReduceMotionEnabled()
    .then((reduceMotion) => update({ reduceMotion }))
    .catch(warnReadFailure);

  subscriptions.push(
    AccessibilityInfo.addEventListener('reduceMotionChanged', (reduceMotion) =>
      update({ reduceMotion }),
    ),
  );

  if (Platform.OS === 'ios') {
    AccessibilityInfo.isReduceTransparencyEnabled()
      .then((reduceTransparency) => update({ reduceTransparency }))
      .catch(warnReadFailure);

    subscriptions.push(
      AccessibilityInfo.addEventListener('reduceTransparencyChanged', (reduceTransparency) =>
        update({ reduceTransparency }),
      ),
    );
  }

  // React Native for Web has no reduce-transparency event; the browser reports it directly.
  if (Platform.OS === 'web' && window.matchMedia) {
    const query = window.matchMedia('(prefers-reduced-transparency: reduce)');
    const handleChange = () => update({ reduceTransparency: query.matches });

    update({ reduceTransparency: query.matches });
    query.addEventListener('change', handleChange);
    subscriptions.push({ remove: () => query.removeEventListener('change', handleChange) });
  }
}

export function subscribeToSystemAccessibility(listener: () => void) {
  listeners.add(listener);

  if (listeners.size === 1) startListening();

  return () => {
    listeners.delete(listener);

    if (listeners.size > 0) return;

    subscriptions.forEach((subscription) => subscription.remove());
    subscriptions = [];
  };
}

export function readSystemAccessibility() {
  return snapshot;
}

import { Platform } from 'react-native';
import type { GlassyUiTheme } from './preferences';

export type GlassTone = 'neutral' | 'blue' | 'green' | 'orange' | 'red' | 'purple';

export type GlassColors = {
  /** Selection, active controls and the prominent button. */
  accent: string;
  accentForeground: string;
  border: string;
  /** The resting fill of fields and unselected controls. */
  controlSurface: string;
  focusRing: string;
  foreground: string;
  /** Extra frost over blurred glass, for clear and tinted glass. */
  glassFill: Record<'clear' | 'tinted', string>;
  invalid: string;
  knob: string;
  mutedForeground: string;
  /** Where glass cannot be drawn: Reduce Transparency. */
  opaqueSurface: string;
  /** Floating layers that must hold 4.5:1 text over any backdrop. */
  overlaySurface: string;
  /** The hairline round a glass edge, and the light it catches along the top. */
  rim: string;
  rimHighlight: string;
  scrim: string;
  shadow: string;
  shadowRaised: string;
  tones: Record<GlassTone, string>;
  track: string;
};

/** Glass stays neutral. Blue marks actions and selection; the tones mark status. */
export const GLASS_COLORS = {
  dark: {
    accent: '#0067d9',
    accentForeground: '#ffffff',
    border: 'rgba(245, 245, 247, 0.22)',
    controlSurface: 'rgba(245, 245, 247, 0.08)',
    focusRing: '#b8b8be',
    foreground: '#f5f5f7',
    glassFill: { clear: 'rgba(255, 255, 255, 0.04)', tinted: 'rgba(28, 28, 30, 0.45)' },
    invalid: '#ff7a8e',
    knob: '#ffffff',
    mutedForeground: '#d1d1d6',
    opaqueSurface: '#2c2c2e',
    overlaySurface: 'rgba(44, 44, 46, 0.78)',
    rim: 'rgba(255, 255, 255, 0.16)',
    rimHighlight: 'rgba(255, 255, 255, 0.34)',
    scrim: 'rgba(0, 0, 0, 0.45)',
    shadow: '0px 1px 2px rgba(0, 0, 0, 0.18), 0px 8px 24px -4px rgba(0, 0, 0, 0.28)',
    shadowRaised: '0px 2px 6px rgba(0, 0, 0, 0.2), 0px 30px 60px -18px rgba(0, 0, 0, 0.55)',
    tones: {
      neutral: '#8e8e93',
      blue: '#78b7ff',
      green: '#33d69f',
      orange: '#ffbd38',
      red: '#ff5c7a',
      purple: '#9b80ff',
    },
    track: 'rgba(118, 118, 128, 0.36)',
  },
  light: {
    accent: '#0067d9',
    accentForeground: '#ffffff',
    border: 'rgba(0, 0, 0, 0.14)',
    controlSurface: 'rgba(255, 255, 255, 0.72)',
    focusRing: '#66666a',
    foreground: '#222224',
    glassFill: { clear: 'rgba(255, 255, 255, 0.18)', tinted: 'rgba(255, 255, 255, 0.55)' },
    invalid: '#c4153f',
    knob: '#ffffff',
    mutedForeground: '#505055',
    opaqueSurface: '#ffffff',
    overlaySurface: 'rgba(255, 255, 255, 0.82)',
    rim: 'rgba(255, 255, 255, 0.55)',
    rimHighlight: 'rgba(255, 255, 255, 0.9)',
    scrim: 'rgba(0, 0, 0, 0.16)',
    shadow: '0px 1px 2px rgba(0, 0, 0, 0.06), 0px 8px 24px -6px rgba(0, 0, 0, 0.14)',
    shadowRaised: '0px 2px 6px rgba(0, 0, 0, 0.06), 0px 28px 56px -18px rgba(0, 0, 0, 0.26)',
    tones: {
      neutral: '#8e8e93',
      blue: '#005ec6',
      green: '#14a874',
      orange: '#e8960c',
      red: '#e8345a',
      purple: '#6a4cf0',
    },
    track: 'rgba(118, 118, 128, 0.2)',
  },
} as const satisfies Record<GlassyUiTheme, GlassColors>;

export const GLASS_RADIUS = { md: 16, lg: 24, capsule: 999 } as const;

/** Arrivals ease out; physical responses spring and settle. Exits run shorter than arrivals. */
export const GLASS_MOTION = {
  duration: 200,
  /** React Native for Web has no native driver and warns when asked for one. */
  nativeDriver: Platform.OS !== 'web',
  spring: { damping: 18, mass: 1, stiffness: 260 },
} as const;

import { useCallback, useState } from 'react';

/**
 * State a component owns until its parent passes `value`; then the parent owns it. Either way
 * `onChange` hears every change the component makes.
 */
export function useControllableState<T>(
  value: T | undefined,
  defaultValue: T,
  onChange?: (next: T) => void,
) {
  const [uncontrolled, setUncontrolled] = useState(defaultValue);
  const controlled = value !== undefined;
  const current = controlled ? value : uncontrolled;

  const setValue = useCallback(
    (next: T) => {
      if (!controlled) setUncontrolled(next);

      onChange?.(next);
    },
    [controlled, onChange],
  );

  return [current, setValue] as const;
}

import { BlurView } from 'expo-blur';
import { GlassView } from 'expo-glass-effect';
import { Children, forwardRef } from 'react';
import { Platform, StyleSheet, Text, View, type ViewProps } from 'react-native';
import { useGlassBackdrop } from './glass-backdrop';
import { useGlassTheme } from './glass-provider';
import { resolveGlassMaterial } from './lib/material';
import { GLASS_RADIUS } from './lib/tokens';

export type SurfacePreset = 'subtle' | 'standard' | 'prominent' | 'control' | 'overlay';

export type SurfaceElevation = 'none' | 'base' | 'raised';

export type GlassSurfaceProps = ViewProps & {
  /** Floating glass casts a shadow; glass set into a layout does not. Defaults to base. */
  elevation?: SurfaceElevation;
  /**
   * How much frost: subtle shows the most of what lies behind, prominent the least. Overlay is
   * for floating layers such as dialogs and menus: its denser tint keeps text at 4.5:1 over any
   * backdrop.
   */
  preset?: SurfacePreset;
  /**
   * Colours the glass, as the prominent button's blue does. Use an opaque colour. Where the glass
   * is a blur, the tint covers 92% of it, so white text on a tint that holds 4.5:1 alone still
   * does over a white backdrop.
   */
  tint?: string;
};

// How strongly each preset blurs where the system's glass is unavailable. On the web these
// land on the same blur radii as the CSS glass.
const BLUR_INTENSITY: Record<SurfacePreset, number> = {
  subtle: 40,
  control: 50,
  standard: 70,
  prominent: 90,
  overlay: 90,
};

let warnedAboutAndroidBackdrop = false;

/**
 * The glass material on its own. iOS 26 and later draw the system's own glass; earlier iOS,
 * Android and the web blur what lies behind and light the rim; Reduce Transparency turns the
 * glass opaque. Text children are set in the theme's ink.
 */
export const GlassSurface = forwardRef<View, GlassSurfaceProps>(
  ({ children, elevation = 'base', preset = 'standard', style, tint, ...rest }, ref) => {
    const { colors, preferences } = useGlassTheme();
    const backdrop = useGlassBackdrop();
    const material = resolveGlassMaterial(preferences.reduceTransparency);
    const radius = StyleSheet.flatten(style)?.borderRadius ?? GLASS_RADIUS.md;
    const corners = { borderRadius: radius, borderCurve: 'continuous' } as const;
    const blurTarget = backdrop?.target ?? undefined;

    if (
      Platform.OS === 'android' &&
      material === 'blur' &&
      !backdrop &&
      !warnedAboutAndroidBackdrop
    ) {
      warnedAboutAndroidBackdrop = true;
      console.warn(
        'Glassy UI: Android blurs only what sits inside a GlassBackdrop. Glass outside one is a translucent tint.',
      );
    }

    return (
      <View
        ref={ref}
        style={[
          corners,
          elevation !== 'none' && {
            boxShadow: elevation === 'raised' ? colors.shadowRaised : colors.shadow,
          },
          style,
        ]}
        {...rest}
      >
        {material === 'liquid' ? (
          <GlassView
            style={[StyleSheet.absoluteFill, corners, styles.layer]}
            colorScheme={preferences.theme}
            glassEffectStyle={preset === 'subtle' ? 'clear' : 'regular'}
            tintColor={
              tint ?? (preferences.mode === 'tinted' ? colors.glassFill.tinted : undefined)
            }
          />
        ) : null}
        {material === 'blur' ? (
          <View style={[StyleSheet.absoluteFill, corners, styles.layer, styles.clip]}>
            <BlurView
              style={StyleSheet.absoluteFill}
              intensity={BLUR_INTENSITY[preset]}
              tint={
                preferences.theme === 'dark'
                  ? 'systemUltraThinMaterialDark'
                  : 'systemUltraThinMaterialLight'
              }
              blurMethod={blurTarget ? 'dimezisBlurViewSdk31Plus' : 'none'}
              blurTarget={blurTarget}
            />
            <View
              style={[
                StyleSheet.absoluteFill,
                tint
                  ? { backgroundColor: tint, opacity: 0.92 }
                  : {
                      backgroundColor:
                        preset === 'overlay'
                          ? colors.overlaySurface
                          : colors.glassFill[preferences.mode],
                    },
              ]}
            />
            <View
              style={[
                StyleSheet.absoluteFill,
                corners,
                {
                  boxShadow: `inset 0px 1px 0px ${colors.rimHighlight}, inset 0px 0px 0px 1px ${colors.rim}`,
                },
              ]}
            />
          </View>
        ) : null}
        {material === 'solid' ? (
          <View
            style={[
              StyleSheet.absoluteFill,
              corners,
              styles.layer,
              {
                backgroundColor: tint ?? colors.opaqueSurface,
                borderColor: colors.border,
                borderWidth: StyleSheet.hairlineWidth,
              },
            ]}
          />
        ) : null}
        {Children.map(children, (child) =>
          // Children.map yields null, elements or text; only text needs a Text to render in.
          child === null || child instanceof Object ? (
            child
          ) : (
            <Text style={{ color: tint ? colors.accentForeground : colors.foreground }}>
              {child}
            </Text>
          ),
        )}
      </View>
    );
  },
);

GlassSurface.displayName = 'GlassSurface';

const styles = StyleSheet.create({
  clip: { overflow: 'hidden' },
  layer: { pointerEvents: 'none' },
});

import { BlurTargetView } from 'expo-blur';
import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
  type RefObject,
} from 'react';
import { StyleSheet, View, type ViewProps } from 'react-native';

type BackdropTarget = {
  /** The view Android blurs, once it has mounted. */
  target: RefObject<View | null> | null;
};

const BackdropContext = createContext<BackdropTarget | null>(null);

/** The nearest GlassBackdrop, or null when glass sits outside one. */
export function useGlassBackdrop() {
  return useContext(BackdropContext);
}

export type GlassBackdropProps = ViewProps & {
  /** What the glass sits over: a wallpaper, a photo or the screen's own content. */
  backdrop: ReactNode;
};

/**
 * Lays its children over `backdrop`. iOS and the web blur whatever lies behind glass; Android can
 * only blur a view marked for it, so glass in the children blurs this backdrop there. Glass
 * outside any GlassBackdrop shows on Android as a translucent tint without blur.
 */
export function GlassBackdrop({ backdrop, children, ...rest }: GlassBackdropProps) {
  const targetRef = useRef<View | null>(null);
  const [target, setTarget] = useState<RefObject<View | null> | null>(null);

  // Android's blur reads its target when it mounts or when the target object changes, so the
  // glass gets a fresh object once the backdrop exists.
  useEffect(() => {
    setTarget({ current: targetRef.current });
  }, []);

  const value = useMemo(() => ({ target }), [target]);

  return (
    <View {...rest}>
      <BlurTargetView ref={targetRef} style={StyleSheet.absoluteFill}>
        {backdrop}
      </BlurTargetView>
      <BackdropContext.Provider value={value}>{children}</BackdropContext.Provider>
    </View>
  );
}

import { isGlassEffectAPIAvailable, isLiquidGlassAvailable } from 'expo-glass-effect';

/**
 * How glass is drawn: the system's own glass on iOS 26 and later, a blur of what lies
 * behind on earlier iOS, Android and the web, or an opaque fill under Reduce Transparency.
 */
export type GlassMaterial = 'liquid' | 'blur' | 'solid';

// Both checks return false off iOS. The second guards early iOS 26 builds that lack the API.
const systemGlass = isLiquidGlassAvailable() && isGlassEffectAPIAvailable();

export function resolveGlassMaterial(reduceTransparency: boolean): GlassMaterial {
  if (reduceTransparency) return 'solid';

  return systemGlass ? 'liquid' : 'blur';
}

import { forwardRef } from 'react';
import type { View } from 'react-native';
import { GlassSurface, type GlassSurfaceProps } from './glass-surface';
import { GLASS_RADIUS } from './lib/tokens';

type PanelVariant = 'panel' | 'card' | 'pill';

type PanelElevation = 'base' | 'raised';

export type GlassPanelProps = Omit<GlassSurfaceProps, 'elevation'> & {
  variant?: PanelVariant;
  elevation?: PanelElevation;
};

// Shape and spacing come first, so a consumer's style always wins.
const VARIANT_STYLE = {
  panel: { borderRadius: GLASS_RADIUS.lg, padding: 24 },
  card: { borderRadius: GLASS_RADIUS.md, padding: 20 },
  pill: { borderRadius: GLASS_RADIUS.capsule, paddingHorizontal: 20, paddingVertical: 12 },
} as const;

/** Glass cards, panels and pills for anything that floats above your content. */
export const GlassPanel = forwardRef<View, GlassPanelProps>(
  (
    {
      elevation = 'base',
      variant = 'panel',
      preset = variant === 'pill' ? 'control' : 'standard',
      style,
      ...rest
    },
    ref,
  ) => (
    <GlassSurface
      ref={ref}
      elevation={elevation}
      preset={preset}
      style={[VARIANT_STYLE[variant], style]}
      {...rest}
    />
  ),
);

GlassPanel.displayName = 'GlassPanel';

import {
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react';
import {
  Animated,
  Easing,
  Pressable,
  StyleSheet,
  Text,
  View,
  type GestureResponderEvent,
  type LayoutChangeEvent,
  type PressableProps,
  type StyleProp,
  type ViewProps,
  type ViewStyle,
} from 'react-native';
import { GlassPanel } from './glass-panel';
import { useGlassTheme } from './glass-provider';
import { GlassSurface } from './glass-surface';
import { GlassIcon } from './lib/icons';
import { wrapPlainText } from './lib/plain-text';
import { GLASS_MOTION, GLASS_RADIUS } from './lib/tokens';
import { useControllableState } from './lib/use-controllable-state';

type SingleAccordionProps = {
  /** One item open at a time. The default. */
  type?: 'single';
  /** The open item's value, or an empty string for none. */
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Lets the open item close again, leaving none open. */
  collapsible?: boolean;
};

type MultipleAccordionProps = {
  /** Any number of items open at once. */
  type: 'multiple';
  /** The open items' values. */
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
  /** Every item of a multiple accordion can close. */
  collapsible?: never;
};

export type GlassAccordionProps = ViewProps &
  (SingleAccordionProps | MultipleAccordionProps) & {
    /** Turns off every item. */
    disabled?: boolean;
  };

type AccordionState = {
  /** Whether an open item can close. */
  collapsible: boolean;
  disabled: boolean;
  open: readonly string[];
  toggle: (item: string) => void;
};

type ItemState = {
  disabled: boolean;
  open: boolean;
  value: string;
};

const AccordionContext = createContext<AccordionState | null>(null);

const ItemContext = createContext<ItemState | null>(null);

// Arrivals ease out on the web's curve; exits ease in and run shorter.
const EASE_OUT = Easing.bezier(0.32, 0.72, 0, 1);

const EASE_IN = Easing.bezier(0.42, 0, 1, 1);

// CSS's own ease, which the web chevron turns on.
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);

function useAccordion(component: string) {
  const accordion = useContext(AccordionContext);

  if (!accordion) throw new Error(`${component} must be used within GlassAccordion`);

  return accordion;
}

function useItem(component: string) {
  const item = useContext(ItemContext);

  if (!item) throw new Error(`${component} must be used within GlassAccordionItem`);

  return item;
}

/** A stack of items that open to show more, one at a time or several at once. */
export const GlassAccordion = forwardRef<View, GlassAccordionProps>(
  (
    { collapsible = false, defaultValue, disabled = false, onValueChange, type, value, ...rest },
    ref,
  ) => {
    // Both kinds keep their own state; only the one `type` names is used.
    const [single, setSingle] = useControllableState(
      type === 'multiple' ? undefined : value,
      type === 'multiple' ? '' : (defaultValue ?? ''),
      type === 'multiple' ? undefined : onValueChange,
    );

    const [many, setMany] = useControllableState(
      type === 'multiple' ? value : undefined,
      type === 'multiple' ? (defaultValue ?? []) : [],
      type === 'multiple' ? onValueChange : undefined,
    );

    const toggle = useCallback(
      (item: string) => {
        if (type === 'multiple') {
          setMany(many.includes(item) ? many.filter((entry) => entry !== item) : [...many, item]);

          return;
        }

        if (item !== single) setSingle(item);
        else if (collapsible) setSingle('');
      },
      [collapsible, many, setMany, setSingle, single, type],
    );

    const open = useMemo(
      () => (type === 'multiple' ? many : single ? [single] : []),
      [many, single, type],
    );

    const state = useMemo(
      () => ({ collapsible: type === 'multiple' || collapsible, disabled, open, toggle }),
      [collapsible, disabled, open, toggle, type],
    );

    return (
      <AccordionContext.Provider value={state}>
        <View ref={ref} {...rest} />
      </AccordionContext.Provider>
    );
  },
);

GlassAccordion.displayName = 'GlassAccordion';

export type GlassAccordionItemProps = ViewProps & {
  disabled?: boolean;
  /** Names the item. The accordion's value holds the names of the open items. */
  value: string;
};

/** One item of an accordion: a trigger and the content it opens. */
export const GlassAccordionItem = forwardRef<View, GlassAccordionItemProps>(
  ({ disabled = false, value, ...rest }, ref) => {
    const accordion = useAccordion('GlassAccordionItem');
    const open = accordion.open.includes(value);
    const off = accordion.disabled || disabled;
    const item = useMemo(() => ({ disabled: off, open, value }), [off, open, value]);

    return (
      <ItemContext.Provider value={item}>
        <View ref={ref} {...rest} />
      </ItemContext.Provider>
    );
  },
);

GlassAccordionItem.displayName = 'GlassAccordionItem';

export type GlassAccordionTriggerProps = Omit<PressableProps, 'children' | 'style'> & {
  children?: ReactNode;
  style?: StyleProp<ViewStyle>;
};

/** The glass row that opens and closes its item; its chevron turns to show which. */
export const GlassAccordionTrigger = forwardRef<View, GlassAccordionTriggerProps>(
  ({ children, disabled, onPress, onPressIn, onPressOut, style, ...rest }, ref) => {
    const { colors, preferences } = useGlassTheme();
    const accordion = useAccordion('GlassAccordionTrigger');
    const item = useItem('GlassAccordionTrigger');
    const [turn] = useState(() => new Animated.Value(item.open ? 1 : 0));
    const [press] = useState(() => new Animated.Value(0));
    const off = Boolean(disabled) || item.disabled;
    const reduceMotion = preferences.reduceMotion;

    useEffect(() => {
      if (reduceMotion) {
        turn.setValue(item.open ? 1 : 0);

        return;
      }

      const animation = Animated.timing(turn, {
        duration: GLASS_MOTION.duration,
        easing: EASE,
        toValue: item.open ? 1 : 0,
        useNativeDriver: GLASS_MOTION.nativeDriver,
      });

      animation.start();

      return () => animation.stop();
    }, [item.open, reduceMotion, turn]);

    const handlePress = useCallback(
      (event: GestureResponderEvent) => {
        onPress?.(event);
        accordion.toggle(item.value);
      },
      [accordion, item.value, onPress],
    );

    // A finger lights the glass, as it lights a button.
    const handlePressIn = useCallback(
      (event: GestureResponderEvent) => {
        onPressIn?.(event);

        if (reduceMotion) {
          press.setValue(1);

          return;
        }

        Animated.timing(press, {
          duration: 90,
          easing: Easing.out(Easing.quad),
          toValue: 1,
          useNativeDriver: GLASS_MOTION.nativeDriver,
        }).start();
      },
      [onPressIn, press, reduceMotion],
    );

    const handlePressOut = useCallback(
      (event: GestureResponderEvent) => {
        onPressOut?.(event);

        if (reduceMotion) {
          press.setValue(0);

          return;
        }

        Animated.timing(press, {
          duration: GLASS_MOTION.duration,
          easing: EASE,
          toValue: 0,
          useNativeDriver: GLASS_MOTION.nativeDriver,
        }).start();
      },
      [onPressOut, press, reduceMotion],
    );

    return (
      <Pressable
        ref={ref}
        accessibilityRole="button"
        // An open item that cannot close announces itself as unavailable, as on the web.
        accessibilityState={{
          disabled: off || (item.open && !accordion.collapsible),
          expanded: item.open,
        }}
        disabled={off}
        onPress={handlePress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
        style={[off && styles.disabled, style]}
        {...rest}
      >
        <GlassSurface elevation="none" preset="control" style={styles.trigger}>
          <View style={[StyleSheet.absoluteFill, styles.clip]}>
            <Animated.View
              style={[StyleSheet.absoluteFill, { backgroundColor: colors.rim, opacity: press }]}
            />
          </View>
          <View style={styles.label}>
            {wrapPlainText(children, (text) => (
              <Text style={[styles.labelText, { color: colors.foreground }]}>{text}</Text>
            ))}
          </View>
          <Animated.View
            style={{
              transform: [
                {
                  rotate: turn.interpolate({ inputRange: [0, 1], outputRange: ['0deg', '180deg'] }),
                },
              ],
            }}
          >
            <GlassIcon
              color={colors.mutedForeground}
              name="chevron-down"
              size={16}
              strokeWidth={1.6}
            />
          </Animated.View>
        </GlassSurface>
      </Pressable>
    );
  },
);

GlassAccordionTrigger.displayName = 'GlassAccordionTrigger';

export type GlassAccordionContentProps = ViewProps;

/**
 * The glass card an item opens, unrolling like a curtain; Reduce Motion opens and closes it at
 * once. `style` lays out what sits inside the card.
 */
export const GlassAccordionContent = forwardRef<View, GlassAccordionContentProps>(
  ({ children, onLayout, style, ...rest }, ref) => {
    const { colors, preferences } = useGlassTheme();
    const item = useItem('GlassAccordionContent');
    const [height, setHeight] = useState(0);
    const [unfold] = useState(() => new Animated.Value(item.open ? 1 : 0));

    useEffect(() => {
      if (preferences.reduceMotion) {
        unfold.setValue(item.open ? 1 : 0);

        return;
      }

      const animation = Animated.timing(unfold, {
        duration: item.open ? 300 : 220,
        easing: item.open ? EASE_OUT : EASE_IN,
        toValue: item.open ? 1 : 0,
        // Height is layout, which only the JavaScript driver can animate.
        useNativeDriver: false,
      });

      animation.start();

      return () => animation.stop();
    }, [item.open, preferences.reduceMotion, unfold]);

    // The content keeps its full height inside the folded card, so it can be measured shut.
    const measure = useCallback(
      (event: LayoutChangeEvent) => {
        onLayout?.(event);
        setHeight(event.nativeEvent.layout.height);
      },
      [onLayout],
    );

    return (
      <Animated.View
        accessibilityElementsHidden={!item.open}
        importantForAccessibility={item.open ? 'auto' : 'no-hide-descendants'}
        style={{
          // Until the content is measured, an open item takes its natural height.
          height:
            height > 0
              ? unfold.interpolate({ inputRange: [0, 1], outputRange: [0, height] })
              : item.open
                ? undefined
                : 0,
          marginTop: unfold.interpolate({ inputRange: [0, 1], outputRange: [0, 8] }),
          pointerEvents: item.open ? 'auto' : 'none',
        }}
      >
        {/* The card clips what it holds, not its own shadow, and shrinks with the row. */}
        <GlassPanel style={styles.card} variant="card">
          <View ref={ref} onLayout={measure} style={[styles.content, style]} {...rest}>
            {wrapPlainText(children, (text) => (
              <Text style={[styles.contentText, { color: colors.foreground }]}>{text}</Text>
            ))}
          </View>
        </GlassPanel>
      </Animated.View>
    );
  },
);

GlassAccordionContent.displayName = 'GlassAccordionContent';

const styles = StyleSheet.create({
  card: { flexGrow: 1, flexShrink: 1, overflow: 'hidden', padding: 0 },
  clip: {
    borderCurve: 'continuous',
    borderRadius: GLASS_RADIUS.md,
    overflow: 'hidden',
    pointerEvents: 'none',
  },
  content: { flexShrink: 0, padding: 20 },
  contentText: { fontSize: 14, lineHeight: 20 },
  disabled: { opacity: 0.45 },
  label: { flex: 1 },
  labelText: { fontSize: 16, fontWeight: '500', lineHeight: 24 },
  // The trigger shares the content card's corner radius, as on the web.
  trigger: {
    alignItems: 'center',
    borderCurve: 'continuous',
    borderRadius: GLASS_RADIUS.md,
    flexDirection: 'row',
    gap: 12,
    justifyContent: 'space-between',
    paddingHorizontal: 16,
    paddingVertical: 12,
  },
});

import { View } from 'react-native';
import Svg, { Path } from 'react-native-svg';

export type GlassIconName =
  | 'check'
  | 'chevron-down'
  | 'chevron-right'
  | 'close'
  | 'dash'
  | 'danger'
  | 'info'
  | 'success'
  | 'warning';

// The web components' own strokes, drawn on a 20-point grid.
const PATHS = {
  check: ['M4.5 10.5 8.25 14.25 15.5 6.25'],
  'chevron-down': ['M5 7.5l5 5 5-5'],
  'chevron-right': ['M7.5 4.4 13.1 10l-5.6 5.6'],
  close: ['M5.5 5.5l9 9m0-9l-9 9'],
  dash: ['M5 10h10'],
  danger: ['M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14Z', 'M7.6 7.6l4.8 4.8', 'M12.4 7.6l-4.8 4.8'],
  info: ['M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14Z', 'M10 9.2v4.1', 'M10 6.7h.01'],
  success: ['M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14Z', 'M6.9 10.2l2.2 2.2 4-4.4'],
  warning: ['M10 3.6 17 16H3L10 3.6Z', 'M10 8.4v3.4', 'M10 14h.01'],
} as const satisfies Record<GlassIconName, readonly string[]>;

export type GlassIconProps = {
  color: string;
  name: GlassIconName;
  size?: number;
  strokeWidth?: number;
};

/** A stroked glyph from the library's small icon set. Decorative; label its control instead. */
export function GlassIcon({ color, name, size = 20, strokeWidth = 1.8 }: GlassIconProps) {
  // The hiding lives on a View: on the web, Svg passes its props to a bare <svg> element.
  return (
    <View
      accessibilityElementsHidden
      importantForAccessibility="no-hide-descendants"
      style={{ height: size, width: size }}
    >
      <Svg width={size} height={size} viewBox="0 0 20 20" fill="none">
        {PATHS[name].map((path) => (
          <Path
            key={path}
            d={path}
            stroke={color}
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={strokeWidth}
          />
        ))}
      </Svg>
    </View>
  );
}

import { Children, isValidElement, type ReactNode } from 'react';

/**
 * Sets plain text inside a Text, which React Native needs to render it. Content that is all text
 * becomes one Text; beside elements such as icons, each run of text gets its own.
 */
export function wrapPlainText(node: ReactNode, render: (text: ReactNode) => ReactNode) {
  const parts = Children.toArray(node);

  if (parts.length === 0) return null;

  if (parts.every((part) => !isValidElement(part))) return render(node);

  return Children.map(node, (part) => (isValidElement(part) ? part : render(part)));
}

/** The words in `node` when it is only text, to name a control for assistive technology. */
export function plainTextOf(node: ReactNode) {
  const parts = Children.toArray(node);

  return parts.length > 0 && parts.every((part) => !isValidElement(part))
    ? parts.join('')
    : undefined;
}
